SELECT (
    SELECT COUNT(bond_id)
    FROM bond
    WHERE molecule_id = 'TR006' AND bond_type = '='
) AS double_bond_count,
(
    SELECT label
    FROM molecule
    WHERE molecule_id = 'TR006'
) AS is_carcinogenic;

